public class ConcurrentAuditLogger {
    private final StringBuffer auditBuffer = new StringBuffer();
    private int entryCount = 0;

    public synchronized void log(String worker, String txnId) {
        auditBuffer.append("[").append(worker).append("] ")
                   .append("Transaction ").append(txnId)
                   .append(" Verified\n");
        entryCount++;
    }

    public String getLogs() {
        return auditBuffer.toString();
    }

    public int getCount() {
        return entryCount;
    }

    public static void main(String[] args) throws InterruptedException {
        ConcurrentAuditLogger logger = new ConcurrentAuditLogger();
        Thread t1 = new Thread(() -> { logger.log("Thread-1", "TXN-101"); logger.log("Thread-1", "TXN-104"); });
        Thread t2 = new Thread(() -> { logger.log("Thread-2", "TXN-102"); logger.log("Thread-2", "TXN-105"); });
        Thread t3 = new Thread(() -> { logger.log("Thread-3", "TXN-103"); logger.log("Thread-3", "TXN-106"); });

        t1.start(); t2.start(); t3.start();
        t1.join(); t2.join(); t3.join();

        System.out.println("--- Shared Audit Log ---\n" + logger.getLogs());
        System.out.println("Total Log Entries: " + logger.getCount());
    }
}

