public class DynamicSqlQueryBuilder {
    private final StringBuilder query = new StringBuilder();
    private boolean hasWhere = false;

    public DynamicSqlQueryBuilder(String table, String... columns) {
        query.append("SELECT ").append(String.join(", ", columns))
             .append(" FROM ").append(table);
    }

    public DynamicSqlQueryBuilder andWhere(String condition) {
        if (!hasWhere) {
            query.append(" WHERE ").append(condition);
            hasWhere = true;
        } else {
            query.append(" AND ").append(condition);
        }
        return this;
    }

    public DynamicSqlQueryBuilder orderBy(String column, boolean ascending) {
        query.append(" ORDER BY ").append(column)
             .append(ascending ? " ASC" : " DESC");
        return this;
    }

    public String build() {
        return query.append(";").toString();
    }

    public static void main(String[] args) {
        String sql = new DynamicSqlQueryBuilder("trainees", "id", "name", "gpa", "hub")
                .andWhere("hub = 'Barrackpore'")
                .andWhere(String.format("gpa >= %.2f", 8.5))
                .andWhere("is_active = 1")
                .orderBy("gpa", false)
                .build();
        System.out.println("Generated SQL:\n" + sql);
    }
}

