public class MarkdownToHtmlParser {
    public static String parseMarkdown(String markdown) {
        StringBuilder html = new StringBuilder();
        String[] lines = markdown.split("\n");
        boolean inList = false;

        for (String line : lines) {
            line = line.trim();
            if (line.startsWith("# ")) {
                html.append("<h1>").append(line.substring(2)).append("</h1>\n");
            } else if (line.startsWith("- ")) {
                if (!inList) {
                    html.append("<ul>\n");
                    inList = true;
                }
                String item = line.substring(2)
                                  .replaceAll("\\*\\*(.*?)\\*\\*", "<strong>$1</strong>")
                                  .replaceAll("\\*(.*?)\\*", "<em>$1</em>");
                html.append("  <li>").append(item).append("</li>\n");
            } else {
                if (inList) {
                    html.append("</ul>\n");
                    inList = false;
                }
                if (!line.isEmpty()) {
                    html.append("<p>").append(line).append("</p>\n");
                }
            }
        }
        if (inList) html.append("</ul>\n");
        return html.toString().trim();
    }

    public static void main(String[] args) {
        String md = "# Welcome to Java\n- Learn **StringBuilder**\n- Master *Formatting*";
        System.out.println(parseMarkdown(md));
    }
}

public class PalindromeVerifier {
    public static boolean isPalindrome(String input) {
        // Clean text to alphanumeric lowercase only
        StringBuilder clean = new StringBuilder();
        for (char ch : input.toCharArray()) {
            if (Character.isLetterOrDigit(ch)) {
                clean.append(Character.toLowerCase(ch));
            }
        }

        String forward = clean.toString();
        String backward = clean.reverse().toString();

        System.out.println("Original Text: " + input);
        System.out.println("Cleaned Text : " + forward);
        System.out.println("Reversed Text: " + backward);
        return forward.equals(backward);
    }

    public static void main(String[] args) {
        boolean result = isPalindrome("A man, a plan, a canal: Panama!");
        System.out.println("Is Palindrome: " + result);
    }
}

