public class UrlQueryBuilder {
    private final StringBuilder url = new StringBuilder();
    private boolean firstParam = true;

    public UrlQueryBuilder(String baseUrl) {
        url.append(baseUrl);
    }

    public UrlQueryBuilder addParam(String key, Object value) {
        url.append(firstParam ? '?' : '&');
        firstParam = false;
        String encodedVal = URLEncoder.encode(String.valueOf(value), StandardCharsets.UTF_8);
        url.append(key).append('=').append(encodedVal);
        return this;
    }

    public String build() {
        return url.toString();
    }

    public static void main(String[] args) {
        String endpoint = new UrlQueryBuilder("https://api.coderaccotax.com/search")
                .addParam("query", "Java Core")
                .addParam("hub", "Barrackpore")
                .addParam("page", 1)
                .build();
        System.out.println("Constructed URL:\n" + endpoint);
    }
}

public class BatchSqlInsertGenerator {
    public static String buildBatchInsert(String table, Object[][] rows) {
        StringBuilder sb = new StringBuilder(256);
        sb.append("INSERT INTO ").append(table).append(" (id, name, score) VALUES\n");

        for (Object[] row : rows) {
            sb.append(String.format("  (%d, '%s', %.2f),\n", (int) row[0], (String) row[1], (double) row[2]));
        }

        // Remove trailing ",\n" using setLength
        sb.setLength(sb.length() - 2);
        sb.append(";");
        return sb.toString();
    }

    public static void main(String[] args) {
