    }
}

public class HexDumpFormatter {
    public static String formatHexDump(byte[] data) {
        StringBuilder out = new StringBuilder();
        out.append(String.format("%-8s %-48s  %s%n", "OFFSET", "HEX DUMP", "ASCII"));
        out.append("----------------------------------------------------------------\n");

        for (int i = 0; i < data.length; i += 16) {
            // Offset header
            out.append(String.format("%04X     ", i));

            // Hex bytes
            StringBuilder hexPart = new StringBuilder();
            StringBuilder asciiPart = new StringBuilder();

            for (int j = 0; j < 16; j++) {
                if (i + j < data.length) {
                    byte b = data[i + j];
                    hexPart.append(String.format("%02X ", b));
                    char c = (char) b;
                    asciiPart.append(c >= 32 && c <= 126 ? c : '.');
                } else {
                    hexPart.append("   ");
                }
            }
            out.append(String.format("%-48s  %s%n", hexPart.toString(), asciiPart.toString()));
        }
        return out.toString();
    }

    public static void main(String[] args) {
        byte[] data = "Hello, Barrackpore!".getBytes();
        System.out.print(formatHexDump(data));
    }
}

public class AsciiTableGenerator {
    public static String renderTable(String[] headers, String[][] rows) {
        int cols = headers.length;
        int[] widths = new int[cols];
        for (int c = 0; c < cols; c++) widths[c] = headers[c].length();
        for (String[] row : rows) {
            for (int c = 0; c < cols; c++) widths[c] = Math.max(widths[c], row[c].length());
        }

        StringBuilder sb = new StringBuilder();
        String border = buildBorder(widths);
        sb.append(border).append("\n");

        // Header row
        sb.append("| ");
        for (int c = 0; c < cols; c++) {
            sb.append(String.format("%-" + widths[c] + "s | ", headers[c]));
        }
        sb.append("\n").append(border).append("\n");

        // Data rows
        for (String[] row : rows) {
            sb.append("| ");
            for (int c = 0; c < cols; c++) {
                sb.append(String.format("%-" + widths[c] + "s | ", row[c]));
            }
            sb.append("\n");
        }
        sb.append(border);
        return sb.toString();
    }

    private static String buildBorder(int[] widths) {
        StringBuilder b = new StringBuilder("+");
        for (int w : widths) {
            b.append("-".repeat(w + 2)).append("+");
        }
        return b.toString();
    }

    public static void main(String[] args) {
        String[] headers = {"ID", "STUDENT NAME", "GRADE", "CITY"};
        String[][] rows = {
            {"101", "Joydeep Banerjee", "A+", "Barrackpore"},
            {"102", "Sourav Mukherjee", "A", "Shyamnagar"},
            {"103", "Tina Karmakar", "A+", "Ichapore"}
        };
        System.out.println(renderTable(headers, rows));
    }
}

