public class TextPerformanceBenchmark {
    private static final int ITERATIONS = 30000;

    public static void main(String[] args) {
        // 1. String (+)
        long start = System.currentTimeMillis();
        String str = "";
        for (int i = 0; i < ITERATIONS; i++) {
            str += "a";
        }
        long strTime = System.currentTimeMillis() - start;

        // 2. StringBuilder
        start = System.currentTimeMillis();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < ITERATIONS; i++) {
            sb.append("a");
        }
        long sbTime = System.currentTimeMillis() - start;

        // 3. StringBuffer
        start = System.currentTimeMillis();
        StringBuffer sbuf = new StringBuffer();
        for (int i = 0; i < ITERATIONS; i++) {
            sbuf.append("a");
        }
        long sbufTime = System.currentTimeMillis() - start;

        System.out.println("Benchmark Results (" + ITERATIONS + " iterations):");
        System.out.printf("1. String (+) Concatenation : %4d ms  [High GC Churn, O(N^2)]%n", strTime);
        System.out.printf("2. StringBuilder (Mutable)  : %4d ms  [Fastest, Zero Lock, O(N)]%n", sbTime);
        System.out.printf("3. StringBuffer (Sync)      : %4d ms  [Thread-Safe Lock Cost, O(N)]%n", sbufTime);
        System.out.println("Conclusion: Always use StringBuilder for intensive single-threaded loop modifications.");
    }
}

public class DnaSequenceEngine {
    public static String getReverseComplement(String dna) {
        StringBuilder sb = new StringBuilder(dna);
        // Replace with complements
        for (int i = 0; i < sb.length(); i++) {
            char ch = sb.charAt(i);
            switch (ch) {
                case 'A' -> sb.setCharAt(i, 'T');
                case 'T' -> sb.setCharAt(i, 'A');
                case 'C' -> sb.setCharAt(i, 'G');
                case 'G' -> sb.setCharAt(i, 'C');
            }
        }
        String complement = sb.toString();
        String reverseComp = sb.reverse().toString();

        System.out.println("Original Strand   : " + dna);
        System.out.println("Complement Strand : " + complement);
        System.out.println("Reverse Complement: " + reverseComp);
        return reverseComp;
    }

    public static void main(String[] args) {
        getReverseComplement("ATGCGATCGAAT");
    }
}

