public class PojoCodeGenerator {
    public static String generatePojo(String className, String[][] fields) {
        StringBuilder fieldDecls = new StringBuilder();
        StringBuilder constructorParams = new StringBuilder();
        StringBuilder constructorBody = new StringBuilder();
        StringBuilder gettersSetters = new StringBuilder();

        for (String[] field : fields) {
            String type = field[0];
            String name = field[1];
            String capName = Character.toUpperCase(name.charAt(0)) + name.substring(1);

            fieldDecls.append(String.format("    private %s %s;%n", type, name));
            constructorParams.append(String.format("%s %s, ", type, name));
            constructorBody.append(String.format("        this.%s = %s;%n", name, name));
            gettersSetters.append(String.format("    public %s get%s() { return %s; }%n", type, capName, name));
            gettersSetters.append(String.format("    public void set%s(%s %s) { this.%s = %s; }%n", capName, type, name, name, name));
        }

        if (constructorParams.length() > 2) {
            constructorParams.setLength(constructorParams.length() - 2);
        }

        return """
                public class %s {
                %s
                    public %s(%s) {
                %s    }

                %s}
                """.formatted(className, fieldDecls, className, constructorParams, constructorBody, gettersSetters);
    }

    public static void main(String[] args) {
        String[][] fields = {
            {"int", "id"},
            {"String", "name"},
            {"double", "score"}
        };
        System.out.println(generatePojo("Trainee", fields));
    }
}

