public class TelemetryRingBuffer {
    private final StringBuffer buffer = new StringBuffer();
    private int totalMetrics = 0;

    public synchronized void recordMetric(int status, int latencyMs) {
        buffer.append("[STATUS: ").append(status)
              .append(", LATENCY: ").append(latencyMs).append("ms]\n");
        totalMetrics++;
    }

    public synchronized String extractSnapshotAndClear() {
        String snapshot = buffer.toString();
        buffer.setLength(0); // clear for next window
        return snapshot;
    }

    public synchronized int getTotalMetrics() { return totalMetrics; }

    public static void main(String[] args) throws InterruptedException {
        TelemetryRingBuffer telemetry = new TelemetryRingBuffer();
        Thread t1 = new Thread(() -> telemetry.recordMetric(200, 12));
        Thread t2 = new Thread(() -> telemetry.recordMetric(200, 18));
        Thread t3 = new Thread(() -> telemetry.recordMetric(500, 45));
        Thread t4 = new Thread(() -> telemetry.recordMetric(200, 15));

        t1.start(); t2.start(); t3.start(); t4.start();
        t1.join(); t2.join(); t3.join(); t4.join();

        System.out.println("--- Telemetry Snapshot ---\n" + telemetry.extractSnapshotAndClear().trim());
        System.out.println("Total Metrics Recorded: " + telemetry.getTotalMetrics());
    }
}

public class RomanNumeralConverter {
    private static final int[] VALUES = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
    private static final String[] SYMBOLS = {"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"};

    public static String toRoman(int num) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < VALUES.length; i++) {
            while (num >= VALUES[i]) {
                num -= VALUES[i];
                sb.append(SYMBOLS[i]);
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        System.out.println("Integer: 1994 -> Roman: " + toRoman(1994));
        System.out.println("Integer: 2026 -> Roman: " + toRoman(2026));
        System.out.println("Integer: 49   -> Roman: " + toRoman(49));
    }
}

